/* Community Health Center replica – shared styles */
:root {
  --color-bg: #fafafa;
  --color-fg: #222;
  --color-primary: #0066cc;
  --color-primary-dark: #004c99;
  --color-accent: #009900;
  --color-muted: #666;
  --color-border: #ccc;
  --color-error: #d93025;
  --color-success: #1e8e3e;
  --font-sans: system-ui, sans-serif;
  --radius: 4px;
  --gap: 1rem;
}

/* Reset */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html { font-size: 100%; scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: var(--color-fg);
  line-height: 1.5;
}
img, svg { max-width: 100%; height: auto; display: block; }
a { color: var(--color-primary); text-decoration: underline; }
a:hover, a:focus { color: var(--color-primary-dark); }
button, input, select, textarea {
  font: inherit;
}

/* Skip link */
.skip-link {
  position: absolute;
  left: -999px;
  top: auto;
  width: 1px;
  height: 1px;
  overflow: hidden;
}
.skip-link:focus {
  left: 1rem;
  top: 1rem;
  width: auto;
  height: auto;
  background: #000;
  color: #fff;
  padding: .5rem 1rem;
  z-index: 100;
}

/* Layout */
header, nav, main, footer { padding: var(--gap); }
header {
  background: var(--color-primary);
  color: #fff;
}
nav ul {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: var(--gap);
}
nav a {
  color: #fff;
  text-decoration: none;
}
nav a:hover, nav a:focus { text-decoration: underline; }

main { max-width: 80ch; margin: 0 auto; }
footer {
  background: var(--color-muted);
  color: #fff;
  font-size: .875rem;
  text-align: center;
}

/* Focus visible */
:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

/* Hero */
.hero {
  text-align: center;
  padding: 3rem var(--gap);
  background: #e6f2ff;
}
.hero h1 { margin-top: 0; font-size: 2rem; }
.hero p { margin: 1rem 0; }
.hero .btn {
  display: inline-block;
  padding: .75rem 1.5rem;
  background: var(--color-accent);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
}
.hero .btn:hover, .hero .btn:focus { background: #007700; }

/* Service bands */
.service-bands {
  display: grid;
  gap: var(--gap);
}
@media (min-width: 480px) {
  .service-bands { grid-template-columns: repeat(2, 1fr); }
}
@media (min-width: 768px) {
  .service-bands { grid-template-columns: repeat(3, 1fr); }
}
.service-band {
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: var(--gap);
  background: #fff;
}
.service-band h2 { margin-top: 0; }
.service-band[aria-expanded="false"] .service-details { display: none; }
.service-band[aria-expanded="true"] .service-details { display: block; }
.service-details { margin-top: 1rem; }

/* Provider listing */
.provider-grid {
  display: grid;
  gap: var(--gap);
}
@media (min-width: 480px) {
  .provider-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (min-width: 768px) {
  .provider-grid { grid-template-columns: repeat(3, 1fr); }
}
.provider-card {
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: var(--gap);
  background: #fff;
}
.provider-card h3 { margin-top: 0; }

/* Location list */
.location-list { list-style: none; }
.location-item {
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: var(--gap);
  margin-bottom: var(--gap);
  background: #fff;
}

/* Forms */
form { display: grid; gap: .75rem; max-width: 400px; }
label { font-weight: 600; }
input, select, textarea {
  width: 100%;
  padding: .5rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
}
input:focus, select:focus, textarea:focus {
  outline: 2px solid var(--color-primary);
}
.error-message {
  color: var(--color-error);
  font-size: .875rem;
}
.error-summary {
  background: #ffe6e6;
  border: 1px solid var(--color-error);
  color: var(--color-error);
  padding: .75rem;
  margin-bottom: var(--gap);
  display: none;
}

/* Modal */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.5);
  display: none;
  align-items: center;
  justify-content: center;
}
.modal-backdrop[aria-hidden="false"] { display: flex; }
.modal {
  background: #fff;
  border-radius: var(--radius);
  padding: 2rem;
  width: 90%;
  max-width: 400px;
  position: relative;
}
.modal-close {
  position: absolute;
  top: .5rem;
  right: .5rem;
  background: transparent;
  border: none;
  font-size: 1.25rem;
  line-height: 1;
  cursor: pointer;
}

/* Hide decorative images */
img[alt=""] { display: none; }
</style>
