    renderDoctors(displayed);
    const filterInput = document.querySelector('[data-component="doctor-filter"]');
    filterInput.addEventListener('input', () => {
      const term = filterInput.value.trim().toLowerCase();
      const filtered = displayed.filter(d =>
        d.name.toLowerCase().includes(term) ||
        d.specialty.toLowerCase().includes(term)
      );
      renderDoctors(filtered);
    });
    filterInput.addEventListener('keydown', e => {
      if (e.key === 'Escape') {
        filterInput.value = '';
        filterInput.dispatchEvent(new Event('input'));
        // reset to primary care list
        displayed = doctors.filter(d => primarySpecialties.includes(d.specialty));
        renderDoctors(displayed);
      }
    });
  </script>
</body>
</html>
