      { id: 2, name: 'UnitedHealthcare', networkTier: 'In-Network' },
      { id: 3, name: 'Aetna', networkTier: 'In-Network' },
      { id: 4, name: 'Cigna', networkTier: 'In-Network' }
    ];
    const list = document.querySelector('[data-component="insurance-list"]');
    insurancePlans.forEach(plan => {
      const li = document.createElement('li');
      li.textContent = `${plan.name} – ${plan.networkTier}`;
      list.appendChild(li);
    });
